    /** Based on: export function separateStrings(
     string: string,
     offset: abstracts.arrays.Offset,
     separateString: string,
     strings: string[],
     ) {
     let ix = string.indexOf(separateString, offset);
     while (ix !== -1) {
     strings.push(string.substring(offset, ix + 1));
     offset = ix + 1;
     ix = string.indexOf(separateString, offset);
     }

     if (offset < string.length) {
     strings.push(string.substring(offset));
     }

     return strings;
     } */
    separateStrings(this: string, offset: abstracts.arrays.Offset, separateString: string, strings: string[]): string[];

    /** Based on: export function preExtractPath(filePath: string, equalPath: string): string {
     const parts: string[] = filePath.split('/');
     const startIndex: number = parts.indexOf(equalPath);
     if (startIndex !== -1) {
     const result: string = parts.slice(0, startIndex).join('/');
     return result;
     } else {
     throw new exceptions.ArgumentException('Path not found', { filePath, equalPath });
     }
     } */
    preExtractPath(this: string, equalPath: string): string;

